using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Qms.Domain.Entities;

namespace Qms.Infrastructure.Persistence.Configurations;

/// <summary>Common mapping: table name, uuid key generated by the application, audit columns.</summary>
internal abstract class EntityConfiguration<TEntity>(string tableName) : IEntityTypeConfiguration<TEntity>
    where TEntity : Entity
{
    public void Configure(EntityTypeBuilder<TEntity> builder)
    {
        builder.ToTable(tableName);
        builder.HasKey(entity => entity.Id);
        builder.Property(entity => entity.Id).ValueGeneratedNever();
        builder.Property(entity => entity.CreatedAt).IsRequired();
        builder.Property(entity => entity.UpdatedAt).IsRequired();

        if (typeof(ITenantEntity).IsAssignableFrom(typeof(TEntity)))
        {
            // company_id is required and points at company (the composite keys below add the same-company guarantee).
            // The company of a row never changes after insert (backstop for the check in QmsDbContext).
            builder.Property(nameof(ITenantEntity.CompanyId)).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            builder.HasOne<Company>().WithMany().HasForeignKey(nameof(ITenantEntity.CompanyId));
        }

        Map(builder);
    }

    protected abstract void Map(EntityTypeBuilder<TEntity> builder);
}

internal static class ColumnTypes
{
    public const string Money = "numeric(12,2)";
}
